INSERT INTO `patient_new_care` VALUES (120,60,'現病史','手臂皮膚癢, 乾燥, 搔抓, 膕窩後, 後腰際, 臉零星紅疹, 無胃脹不適, 睡不好; 用外用藥水藥膏, 皮膚癢作, 仍有紅疹, 傷口, 用青黛過敏','2025-04-18 05:36:41');
