INSERT INTO `patient_new_care` VALUES (135,118,'主訴','項, 四肢屈側搔癢性紅疹反覆已5年','2025-04-22 02:02:14');
INSERT INTO `patient_new_care` VALUES (136,118,'現病史','AD病史(7歲初作), 未接受治療, 自行使用乳液, 症狀反覆作, 偶出現腹股溝. 目前病灶位於項, 四肢屈側, 成紅疹, 皮紋明顯. 集中內側多, 腿皮膚乾燥, 病灶搔癢, 未影響睡眠. 食納平. 二便平. 晨起打噴嚏, 流鼻水, 偶鼻塞作. 少汗, 膚濕冷. 脖頸,手肘內紅疹, 左大腿膕窩皮膚搔抓紅疹','2025-04-22 02:02:14');
