INSERT INTO `patient_new_care` VALUES (3822,141,'現病史','現病史:三個半月大起四肢關節處起紅疹點與紅疹片,近來臉部 頸部及前胸紅疹加重,皮乾燥脫屑,嚴重時滲流組織液,天氣冷交替明顯時症加重,使用類固醇後略有改善,目前臉部 頸部上背部 手背腳背與四肢關節處有紅疹片件隨脫屑 有輕微搔抓皮膚破損,四肢病灶明顯增厚,臉部大腿經常搔抓 擦西藥有減緩,半夜三點左右搔抓劇烈影響睡眠,近來外陰部處皮膚有發紅.  服藥後易打嗝,打噴嚏,晨起眼腫,球池玩後,腿皮膚嚴重紅腫,','2025-07-17 10:36:20');
INSERT INTO `patient_new_care` VALUES (3821,141,'主訴','主訴:全身皮膚红疹片約四個月','2025-07-17 10:36:20');
