INSERT INTO `patient_new_care` VALUES (7611,2048,'其他傷病史','皮膚方面的（「粟粒腫」在臉上眼周及右側的臉頰。腳趾縫乾癢脫皮..）。胃食道逆流。泌尿道結石。婦科疾病（巧克力囊腫。子宮肌瘤），手術治療：良性的甲狀腺結節性腫瘤。良性的聽神經瘤的腦部開顱手術...）。眼科（青光眼）。肢體上的（拇指外翻~因1994年車禍產生的宿疾。筋骨酸痛）','2025-09-15 06:40:13');
